package com.setuppicker;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Takes the keyboard away from the chatbox while the picker's search box has it.
 *
 * <p>The chatbox reads keys through its key listener. The core Key Remapping plugin only acts while that
 * listener is set (its "chatbox focused" check), so with it removed Key Remapping stands down too: it stops
 * turning W/A/S/D into arrow keys, and Enter no longer unlocks its "Press Enter to Chat" input when all it was
 * meant to do was pick a setup. The listener is put back as soon as the search box loses focus.
 *
 * <p>Client thread only.
 */
@Singleton
public class ChatboxKeyGuard
{
	private final Client client;
	private Object[] savedListener;

	@Inject
	ChatboxKeyGuard(Client client)
	{
		this.client = client;
	}

	/**
	 * @param searchFocused whether the picker currently wants the keyboard
	 */
	public void sync(boolean searchFocused)
	{
		if (searchFocused)
		{
			suspend();
		}
		else
		{
			restore();
		}
	}

	private void suspend()
	{
		final Widget chatbox = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		if (chatbox == null)
		{
			return;
		}
		// Also re-suspends if the game rebuilt the chatbox, and so set the listener again, while searching
		final Object[] listener = chatbox.getOnKeyListener();
		if (listener != null)
		{
			savedListener = listener;
			chatbox.setOnKeyListener((Object[]) null);
		}
	}

	public void restore()
	{
		if (savedListener == null)
		{
			return;
		}
		final Widget chatbox = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		// If the game has set a listener in the meantime, that one is current: leave it
		if (chatbox != null && chatbox.getOnKeyListener() == null)
		{
			chatbox.setOnKeyListener(savedListener);
		}
		savedListener = null;
	}
}

package com.setuppicker;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;

/**
 * Mouse and keyboard handling for the picker. Events that land on the picker, and all typing while its
 * search box has focus, are consumed so they don't also reach the game.
 *
 * <p>Key listeners run in the order they were registered, and other plugins' usually come first. Remapping
 * plugins rewrite key presses and consume typed characters before this listener sees them, so it works from
 * the physical key of each press instead. {@link ChatboxKeyGuard} keeps the chatbox out of the way meanwhile.
 */
@Singleton
public class PickerInput extends MouseAdapter implements KeyListener, MouseWheelListener
{
	private static final int MODIFIER_MASK = InputEvent.CTRL_DOWN_MASK | InputEvent.META_DOWN_MASK
		| InputEvent.ALT_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK;

	private final Client client;
	private final SetupPickerPlugin plugin;
	private final SetupPickerConfig config;
	private final SetupPickerOverlay overlay;
	private final PickerModel model;
	private final PlatformModifier platformModifier;

	// The hotkey's own key press can also produce a typed character, which shouldn't end up in the search box
	private boolean swallowNextTyped;
	private final Set<Integer> swallowedPresses = new HashSet<>();

	@Inject
	PickerInput(Client client, SetupPickerPlugin plugin, SetupPickerConfig config, SetupPickerOverlay overlay,
		PickerModel model, PlatformModifier platformModifier)
	{
		this.platformModifier = platformModifier;
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.overlay = overlay;
		this.model = model;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		final PickerLayout layout = overlay.getLayout();
		if (layout == null || !layout.getBounds().contains(e.getPoint()))
		{
			// clicking back into the game ends the search and dismisses the popup
			if (model.view().isSearchFocused())
			{
				model.resetSearch();
			}
			return e;
		}

		if (SwingUtilities.isLeftMouseButton(e))
		{
			if (layout.isPalette())
			{
				clickRow(layout, e);
			}
			else if (layout.getHeader().contains(e.getPoint()))
			{
				model.resetSearch();
				plugin.setCollapsed(!layout.isCollapsed());
			}
			else if (layout.getSearch() != null && layout.getSearch().contains(e.getPoint()))
			{
				model.setSearchFocused(true);
			}
			else
			{
				clickRow(layout, e);
			}
		}
		e.consume();
		return e;
	}

	private void clickRow(PickerLayout layout, MouseEvent e)
	{
		final int row = layout.rowAt(e.getPoint());
		final PickerModel.View view = model.view();
		final List<PickerRow> rows = view.getRows();
		if (row < 0 || view.getScroll() + row >= rows.size())
		{
			return;
		}
		activate(rows.get(view.getScroll() + row));
	}

	/**
	 * Do what picking a row does: open its Bank Tag, or go to or back from a section's page.
	 */
	private void activate(PickerRow row)
	{
		if (row.isBack())
		{
			model.closeSection();
		}
		else if (row.isHeader())
		{
			// headings are only for show unless sections have pages
			model.openSection(row);
		}
		else
		{
			plugin.activateSetup(row.getSetup());
			model.resetSearch();
		}
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
	{
		final PickerLayout layout = overlay.getLayout();
		if (layout == null || !layout.getBounds().contains(e.getPoint()))
		{
			return e;
		}
		model.scrollBy(e.getWheelRotation());
		e.consume();
		return e;
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		final int code = keyCode(e);
		if (isHotkey(e, code))
		{
			if (model.view().isPaletteOpen())
			{
				model.resetSearch();
			}
			else if (client.getGameState() == GameState.LOGGED_IN)
			{
				model.openPalette();
			}
			else
			{
				return;
			}
			swallowNextTyped = true;
			swallow(e, code);
			return;
		}
		// any other key means the hotkey's typed character, if it had one, has been and gone
		swallowNextTyped = false;

		if (!model.view().isSearchFocused())
		{
			return;
		}

		if (isSelectAll(e, code))
		{
			model.selectQuery();
			swallow(e, code);
			return;
		}

		switch (code)
		{
			case KeyEvent.VK_ESCAPE:
				model.resetSearch();
				break;
			case KeyEvent.VK_ENTER:
				final PickerRow row = model.getSelectedRow();
				if (row != null)
				{
					activate(row);
				}
				else
				{
					model.resetSearch();
				}
				break;
			case KeyEvent.VK_LEFT:
				if (model.view().getQuery().isEmpty())
				{
					// nothing to move through: back out of the section's page
					model.closeSection();
				}
				else
				{
					model.moveCaret(-1);
				}
				break;
			case KeyEvent.VK_RIGHT:
				model.moveCaret(1);
				break;
			case KeyEvent.VK_HOME:
				model.moveCaret(-Integer.MAX_VALUE);
				break;
			case KeyEvent.VK_END:
				model.moveCaret(Integer.MAX_VALUE);
				break;
			case KeyEvent.VK_DELETE:
				model.deleteForward();
				break;
			case KeyEvent.VK_UP:
				model.moveSelection(-1);
				break;
			case KeyEvent.VK_DOWN:
				model.moveSelection(1);
				break;
			case KeyEvent.VK_TAB:
				model.moveSelection(e.isShiftDown() ? -1 : 1);
				break;
			case KeyEvent.VK_PAGE_UP:
				model.pageSelection(-1);
				break;
			case KeyEvent.VK_PAGE_DOWN:
				model.pageSelection(1);
				break;
			case KeyEvent.VK_BACK_SPACE:
				model.backspace();
				break;
			default:
				final char c = typedChar(e, code);
				if (c != 0)
				{
					model.typeChar(c);
				}
				break;
		}
		swallow(e, code);
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		// The search text is built from key presses (see typedChar), so typed events only need keeping from the game
		if (swallowNextTyped || model.view().isSearchFocused())
		{
			swallowNextTyped = false;
			e.consume();
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		// Only releases of presses that were swallowed: a key that was already held when the search started
		// (say, a camera key) must still be seen being released by the game
		if (swallowedPresses.remove(keyCode(e)))
		{
			e.consume();
		}
	}

	private void swallow(KeyEvent e, int code)
	{
		swallowedPresses.add(code);
		e.consume();
	}

	/**
	 * The key that was physically pressed. Listeners registered before this one may have rewritten the event's
	 * key code (Key Remapping turns W into Up, for one), but they leave the extended key code alone, which is
	 * also what RuneLite's own keybinds match on.
	 */
	private static int keyCode(KeyEvent e)
	{
		final int extended = e.getExtendedKeyCode();
		return extended != KeyEvent.VK_UNDEFINED ? extended : e.getKeyCode();
	}

	/**
	 * The character a key press types, or 0 for none. Taken from the press rather than from typed events,
	 * because remapping plugins consume those, and blank the character of the presses they rewrite.
	 */
	private static char typedChar(KeyEvent e, int code)
	{
		if (e.isControlDown() || e.isMetaDown())
		{
			return 0;
		}
		final char c = e.getKeyChar();
		if (c != KeyEvent.CHAR_UNDEFINED)
		{
			return c >= ' ' && c != KeyEvent.VK_DELETE ? c : 0;
		}
		// a rewritten press: work the character out from the key
		if (code >= KeyEvent.VK_A && code <= KeyEvent.VK_Z)
		{
			return (char) ((e.isShiftDown() ? 'A' : 'a') + code - KeyEvent.VK_A);
		}
		if (code >= KeyEvent.VK_0 && code <= KeyEvent.VK_9)
		{
			return (char) ('0' + code - KeyEvent.VK_0);
		}
		if (code >= KeyEvent.VK_NUMPAD0 && code <= KeyEvent.VK_NUMPAD9)
		{
			return (char) ('0' + code - KeyEvent.VK_NUMPAD0);
		}
		switch (code)
		{
			case KeyEvent.VK_SPACE:
				return ' ';
			case KeyEvent.VK_MINUS:
				return '-';
			case KeyEvent.VK_EQUALS:
				return '=';
			default:
				return 0;
		}
	}

	// Ctrl+A or Cmd+A. Either is taken on any platform, as neither means anything else in the search box.
	private static boolean isSelectAll(KeyEvent e, int code)
	{
		final int modifiers = e.getModifiersEx() & MODIFIER_MASK;
		return code == KeyEvent.VK_A && (modifiers == InputEvent.CTRL_DOWN_MASK || modifiers == InputEvent.META_DOWN_MASK);
	}

	private boolean isHotkey(KeyEvent e, int code)
	{
		if (code != config.openKey().getKeyCode() || code == KeyEvent.VK_UNDEFINED)
		{
			return false;
		}
		final int wanted = config.requireModifier() ? platformModifier.get() : 0;
		if ((e.getModifiersEx() & MODIFIER_MASK) != wanted)
		{
			return false;
		}
		// Without a modifier the hotkey is a plain key, which has to stay typeable in the search box
		return wanted != 0 || !model.view().isSearchFocused();
	}
}

package com.setuppicker;

import java.awt.Point;
import java.awt.Rectangle;

/**
 * Where the picker's parts are on the canvas for one frame. Shared by painting and mouse hit-testing.
 */
public final class PickerLayout
{
	static final int HEADER_HEIGHT = 20;
	static final int SEARCH_HEIGHT = 20;
	static final int PADDING = 3;
	static final int GAP = 4;
	static final int ROW_HEIGHT_ICONS = 20;
	static final int ROW_HEIGHT_TEXT = 16;
	static final int FOOTER_HEIGHT = 16;
	static final int COLLAPSED_WIDTH = HEADER_HEIGHT;
	static final int COLLAPSED_LENGTH = 96;

	private final Rectangle bounds;
	private final Rectangle header;
	private final Rectangle search;
	private final Rectangle list;
	private final Rectangle footer;
	private final int rowHeight;
	private final int visibleRows;

	private PickerLayout(Rectangle bounds, Rectangle header, Rectangle search, Rectangle list, Rectangle footer,
		int rowHeight, int visibleRows)
	{
		this.bounds = bounds;
		this.header = header;
		this.search = search;
		this.list = list;
		this.footer = footer;
		this.rowHeight = rowHeight;
		this.visibleRows = visibleRows;
	}

	/**
	 * The hotkey-opened popup: centered horizontally in the game area, in its upper part.
	 *
	 * @param area       the canvas
	 * @param setupCount number of rows to list (setups and section headings), after the search is applied
	 * @param maxRows    most rows to show before scrolling
	 */
	public static PickerLayout computePalette(Rectangle area, int width, int setupCount, int rowHeight, int maxRows)
	{
		width = Math.min(width, area.width);
		final int chrome = HEADER_HEIGHT + SEARCH_HEIGHT + FOOTER_HEIGHT + 4 * PADDING;
		final int fittingRows = Math.max(1, (area.height - chrome) / rowHeight);
		final int visibleRows = Math.max(1, Math.min(setupCount, Math.min(maxRows, fittingRows)));

		final int x = area.x + (area.width - width) / 2;
		// Anchored where it would sit with a full list, so it doesn't jump around as typing narrows the results
		final int fullHeight = chrome + Math.min(maxRows, fittingRows) * rowHeight;
		final int y = area.y + Math.max(0, Math.min(area.height / 6, area.height - fullHeight));

		final Rectangle header = new Rectangle(x, y, width, HEADER_HEIGHT);
		final Rectangle search = new Rectangle(x + PADDING, y + HEADER_HEIGHT + PADDING, width - 2 * PADDING, SEARCH_HEIGHT);
		final Rectangle list = new Rectangle(x + PADDING, search.y + search.height + PADDING, width - 2 * PADDING, visibleRows * rowHeight);
		final Rectangle footer = new Rectangle(x + PADDING, list.y + list.height + PADDING, width - 2 * PADDING, FOOTER_HEIGHT);
		final Rectangle bounds = new Rectangle(x, y, width, footer.y + footer.height + PADDING - y);
		return new PickerLayout(bounds, header, search, list, footer, rowHeight, visibleRows);
	}

	/**
	 * The list docked beside the bank.
	 *
	 * @param bank       bounds of the bank interface
	 * @param preferLeft sit left of the bank when both sides have room
	 * @param uprightTab when collapsed, be a narrow upright tab rather than just the title bar
	 * @param setupCount number of rows to list (setups and section headings), after the search is applied
	 */
	public static PickerLayout compute(Rectangle bank, int canvasWidth, boolean preferLeft, int width,
		boolean collapsed, boolean uprightTab, int setupCount, int rowHeight)
	{
		final boolean upright = collapsed && uprightTab;
		if (upright)
		{
			// A narrow tab standing against the bank's edge with its title running up it
			width = COLLAPSED_WIDTH;
		}
		final int leftX = bank.x - GAP - width;
		final int rightX = bank.x + bank.width + GAP;
		final boolean leftFits = leftX >= 0;
		final boolean rightFits = rightX + width <= canvasWidth;

		final int x;
		if (leftFits && (preferLeft || !rightFits))
		{
			x = leftX;
		}
		else if (rightFits)
		{
			x = rightX;
		}
		else
		{
			// No room on either side (fixed mode): sit on top of the bank's edge instead
			x = preferLeft ? bank.x : bank.x + bank.width - width;
		}
		final int y = bank.y;

		if (upright)
		{
			final Rectangle tab = new Rectangle(x, y, width, Math.min(COLLAPSED_LENGTH, bank.height));
			return new PickerLayout(tab, tab, null, null, null, rowHeight, 0);
		}

		final Rectangle header = new Rectangle(x, y, width, HEADER_HEIGHT);
		if (collapsed)
		{
			// just the title bar
			return new PickerLayout(header, header, null, null, null, rowHeight, 0);
		}
		final Rectangle search = new Rectangle(x + PADDING, y + HEADER_HEIGHT + PADDING, width - 2 * PADDING, SEARCH_HEIGHT);
		final int listY = search.y + search.height + PADDING;
		final int maxRows = Math.max(1, (bank.y + bank.height - listY - PADDING) / rowHeight);
		// always leave one row's worth of space for the "no setups" message
		final int visibleRows = Math.max(1, Math.min(setupCount, maxRows));
		final Rectangle list = new Rectangle(x + PADDING, listY, width - 2 * PADDING, visibleRows * rowHeight);
		final Rectangle bounds = new Rectangle(x, y, width, list.y + list.height + PADDING - y);
		return new PickerLayout(bounds, header, search, list, null, rowHeight, visibleRows);
	}

	public Rectangle getBounds()
	{
		return bounds;
	}

	public Rectangle getHeader()
	{
		return header;
	}

	/**
	 * The search box, or null when collapsed.
	 */
	public Rectangle getSearch()
	{
		return search;
	}

	/**
	 * The area holding the rows, or null when collapsed.
	 */
	public Rectangle getList()
	{
		return list;
	}

	/**
	 * The key hint strip of the popup, or null for the list beside the bank.
	 */
	public Rectangle getFooter()
	{
		return footer;
	}

	public boolean isPalette()
	{
		return footer != null;
	}

	public boolean isCollapsed()
	{
		return list == null;
	}

	/**
	 * Whether this is the collapsed list in its upright tab form.
	 */
	public boolean isUprightTab()
	{
		return list == null && header.height > header.width;
	}

	public int getRowHeight()
	{
		return rowHeight;
	}

	public int getVisibleRows()
	{
		return visibleRows;
	}

	public Rectangle getRow(int row)
	{
		return new Rectangle(list.x, list.y + row * rowHeight, list.width, rowHeight);
	}

	/**
	 * The visible row under the point, or -1.
	 */
	public int rowAt(Point p)
	{
		if (list == null || !list.contains(p))
		{
			return -1;
		}
		return (p.y - list.y) / rowHeight;
	}
}

package com.setuppicker;

import java.awt.Rectangle;

/** Reuses geometry until a dimension, display mode, row count, or layout setting changes. */
final class PickerLayoutCache
{
	private PickerLayout layout;
	private boolean palette;
	private int x, y, areaWidth, areaHeight, canvasWidth, width, count, rowHeight, maxRows;
	private boolean left, collapsed, upright;

	PickerLayout palette(int canvasWidth, int canvasHeight, int width, int count, int rowHeight, int maxRows)
	{
		if (layout == null || !palette || areaWidth != canvasWidth || areaHeight != canvasHeight
			|| this.width != width || this.count != count || this.rowHeight != rowHeight || this.maxRows != maxRows)
		{
			layout = PickerLayout.computePalette(new Rectangle(canvasWidth, canvasHeight), width, count, rowHeight, maxRows);
			palette = true;
			areaWidth = canvasWidth;
			areaHeight = canvasHeight;
			this.width = width;
			this.count = count;
			this.rowHeight = rowHeight;
			this.maxRows = maxRows;
		}
		return layout;
	}

	PickerLayout bank(Rectangle bank, int canvasWidth, boolean left, int width, boolean collapsed,
		boolean upright, int count, int rowHeight)
	{
		if (layout == null || palette || x != bank.x || y != bank.y || areaWidth != bank.width
			|| areaHeight != bank.height || this.canvasWidth != canvasWidth || this.left != left
			|| this.width != width || this.collapsed != collapsed || this.upright != upright
			|| this.count != count || this.rowHeight != rowHeight)
		{
			layout = PickerLayout.compute(bank, canvasWidth, left, width, collapsed, upright, count, rowHeight);
			palette = false;
			x = bank.x;
			y = bank.y;
			areaWidth = bank.width;
			areaHeight = bank.height;
			this.canvasWidth = canvasWidth;
			this.left = left;
			this.width = width;
			this.collapsed = collapsed;
			this.upright = upright;
			this.count = count;
			this.rowHeight = rowHeight;
		}
		return layout;
	}
}

package com.setuppicker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * State of the picker. Written from the client thread (setup data, rendering) and the AWT thread
 * (mouse and keyboard), so every access is synchronized and readers work from an immutable {@link View}.
 */
public class PickerModel
{
	/**
	 * Immutable snapshot of what the picker should currently show.
	 */
	public static final class View
	{
		private final List<PickerRow> rows;
		private final int total;
		private final String activeSetup;
		private final String query;
		private final boolean searchFocused;
		private final boolean paletteOpen;
		private final boolean sectionPages;
		private final boolean querySelected;
		private final int caret;
		private final int scroll;
		private final int selected;

		private View(List<PickerRow> rows, int total, String activeSetup, String query, boolean searchFocused,
			boolean paletteOpen, boolean sectionPages, int scroll, int selected, boolean querySelected, int caret)
		{
			this.caret = caret;
			this.querySelected = querySelected;
			this.sectionPages = sectionPages;
			this.rows = rows;
			this.total = total;
			this.activeSetup = activeSetup;
			this.query = query;
			this.searchFocused = searchFocused;
			this.paletteOpen = paletteOpen;
			this.scroll = scroll;
			this.selected = selected;
		}

		/**
		 * The setups matching the search in display order, each run of them under its section heading when
		 * they are grouped by section.
		 */
		public List<PickerRow> getRows()
		{
			return rows;
		}

		/**
		 * Number of setups before the search was applied.
		 */
		public int getTotal()
		{
			return total;
		}

		public String getActiveSetup()
		{
			return activeSetup;
		}

		public String getQuery()
		{
			return query;
		}

		/**
		 * Whether the whole search text is highlighted, after select all: the next thing typed replaces it.
		 */
		public boolean isQuerySelected()
		{
			return querySelected;
		}

		/**
		 * Where in the search text typing goes: the number of characters before the cursor.
		 */
		public int getCaret()
		{
			return caret;
		}

		public boolean isSearchFocused()
		{
			return searchFocused;
		}

		/**
		 * Whether the hotkey-opened popup is showing. It always has search focus while open.
		 */
		public boolean isPaletteOpen()
		{
			return paletteOpen;
		}

		/**
		 * Whether section headings can be picked, to open the section's own page or to go back from it.
		 */
		public boolean isSectionPages()
		{
			return sectionPages;
		}

		/**
		 * Index into {@link #getRows()} of the first visible row.
		 */
		public int getScroll()
		{
			return scroll;
		}

		/**
		 * Index into {@link #getRows()} of the keyboard selection, which is only on a heading if those can be
		 * picked. Only meaningful while searching.
		 */
		public int getSelected()
		{
			return selected;
		}
	}

	private List<PickerRow> rows = Collections.emptyList();
	private List<PickerRow> filtered = Collections.emptyList();
	private int total;
	private String activeSetup = "";
	private String query = "";
	private boolean searchFocused;
	private boolean paletteOpen;
	private int scroll;
	private int selected;
	private int visibleRows = 1;
	private boolean fuzzySearch;
	private boolean querySelected;
	private int caret;
	private boolean startOnActiveSetup = true;
	// Set while the popup should keep its starting selection in view, until the user scrolls or searches
	private boolean revealSelection;
	private int scrollBeforePalette;
	private boolean sectionPages;
	// heading of the section whose page is showing, or null for the list of sections
	private PickerRow openSection;
	private PickerRow sectionBeforePalette;
	private final SetupMatcher.Workspace matcherWorkspace = new SetupMatcher.Workspace();
	private View lastView;

	public synchronized View view()
	{
		final boolean paged = isPaged();
		if (lastView != null && lastView.rows == filtered && lastView.total == total
			&& lastView.activeSetup.equals(activeSetup) && lastView.query.equals(query)
			&& lastView.searchFocused == searchFocused && lastView.paletteOpen == paletteOpen
			&& lastView.sectionPages == paged && lastView.scroll == scroll && lastView.selected == selected
			&& lastView.querySelected == querySelected && lastView.caret == caret)
		{
			return lastView;
		}
		lastView = new View(filtered, total, activeSetup, query, searchFocused, paletteOpen, paged, scroll, selected,
			querySelected, caret);
		return lastView;
	}

	/**
	 * Show each section on a page of its own, reached from a list of the sections, rather than everything in
	 * one list. Makes no difference when the setups aren't grouped by section.
	 */
	public synchronized void setSectionPages(boolean pages)
	{
		if (sectionPages != pages)
		{
			sectionPages = pages;
			openSection = null;
			sectionBeforePalette = null;
			refilter(true);
		}
	}

	/**
	 * Go to a section's page.
	 *
	 * @param header the section's heading, from the rows of a {@link View}
	 */
	public synchronized void openSection(PickerRow header)
	{
		if (isPaged() && header.isHeader())
		{
			openSection = header;
			query = "";
			caret = 0;
			refilter(true);
		}
	}

	/**
	 * Go back from a section's page to the list of sections, with the section that was open selected.
	 */
	public synchronized void closeSection()
	{
		final PickerRow closed = openSection;
		if (closed == null)
		{
			return;
		}
		openSection = null;
		query = "";
		caret = 0;
		refilter(true);
		for (int i = 0; i < filtered.size(); i++)
		{
			if (filtered.get(i).isHeader() && filtered.get(i).sameSection(closed))
			{
				moveSelection(i - selected);
				break;
			}
		}
	}

	/**
	 * List the setups as they are, without section headings.
	 */
	public synchronized void setSetups(List<SetupEntry> setups)
	{
		final List<PickerRow> newRows = new ArrayList<>(setups.size());
		for (SetupEntry setup : setups)
		{
			newRows.add(PickerRow.of(setup));
		}
		setRows(newRows, setups.size());
	}

	/**
	 * @param newRows  the setups to list. Every heading among them must be followed by at least one setup.
	 * @param newTotal number of setups there are, which is less than the setup rows when some are in several sections
	 */
	public synchronized void setRows(List<PickerRow> newRows, int newTotal)
	{
		rows = Collections.unmodifiableList(new ArrayList<>(newRows));
		total = newTotal;
		// a reload (e.g. after a setup is edited) shouldn't move the list under the user
		refilter(false);
	}

	/**
	 * Whether the popup opens with the selection on the setup that's already open, rather than at the top.
	 */
	public synchronized void setStartOnActiveSetup(boolean start)
	{
		startOnActiveSetup = start;
	}

	/**
	 * Whether a search that finds nothing as typed may match names that are a typo or a few letters away.
	 */
	public synchronized void setFuzzySearch(boolean fuzzy)
	{
		if (fuzzySearch != fuzzy)
		{
			fuzzySearch = fuzzy;
			refilter(false);
		}
	}

	public synchronized void setActiveSetup(String name)
	{
		activeSetup = name == null ? "" : name;
	}

	/**
	 * Told by the overlay how many rows fit, so scrolling can be clamped to it.
	 */
	public synchronized void setVisibleRows(int rows)
	{
		visibleRows = Math.max(1, rows);
		if (revealSelection && selected >= scroll + visibleRows)
		{
			scroll = selected - visibleRows + 1;
		}
		clamp();
	}

	public synchronized void scrollBy(int rows)
	{
		revealSelection = false;
		scroll += rows;
		clamp();
	}

	/**
	 * Focus or unfocus the search box of the list beside the bank.
	 */
	public synchronized void setSearchFocused(boolean focused)
	{
		searchFocused = focused;
		if (focused)
		{
			selected = 0;
			scroll = 0;
			clamp();
		}
	}

	/**
	 * Show the popup with an empty search, ready for typing.
	 */
	public synchronized void openPalette()
	{
		if (!paletteOpen)
		{
			scrollBeforePalette = query.isEmpty() ? scroll : 0;
			sectionBeforePalette = openSection;
		}
		openSection = null;
		paletteOpen = true;
		searchFocused = true;
		query = "";
		caret = 0;
		refilter(true);
		selectActiveSetup();
	}

	/**
	 * Start on the setup that's already open, when it's listed, so that it only takes Enter to close it.
	 */
	private void selectActiveSetup()
	{
		if (!startOnActiveSetup || activeSetup.isEmpty())
		{
			return;
		}
		for (int i = 0; i < filtered.size(); i++)
		{
			final PickerRow row = filtered.get(i);
			if (!row.isHeader() && row.getSetup().getName().equals(activeSetup))
			{
				selected = i;
				// The popup's size isn't known until it is next drawn, so it is scrolled into view then
				revealSelection = true;
				return;
			}
		}
	}

	/**
	 * Highlight the whole search text, so that typing replaces it and Backspace clears it.
	 */
	public synchronized void selectQuery()
	{
		querySelected = searchFocused && !query.isEmpty();
	}

	/**
	 * Move the cursor through the search text. After select all, it lands at the end moved towards.
	 *
	 * @param delta characters to move by; anything past either end stops there
	 */
	public synchronized void moveCaret(int delta)
	{
		if (querySelected)
		{
			querySelected = false;
			caret = delta < 0 ? 0 : query.length();
			return;
		}
		caret = (int) Math.max(0, Math.min((long) caret + delta, query.length()));
	}

	/**
	 * Delete the character after the cursor, or everything after select all.
	 */
	public synchronized void deleteForward()
	{
		if (querySelected)
		{
			query = "";
			caret = 0;
		}
		else if (caret < query.length())
		{
			query = query.substring(0, caret) + query.substring(caret + 1);
		}
		else
		{
			return;
		}
		refilter(true);
	}

	public synchronized void typeChar(char c)
	{
		if (querySelected)
		{
			query = "";
			caret = 0;
		}
		query = query.substring(0, caret) + c + query.substring(caret);
		caret++;
		refilter(true);
	}

	public synchronized void backspace()
	{
		if (!query.isEmpty())
		{
			if (querySelected)
			{
				query = "";
				caret = 0;
			}
			else if (caret > 0)
			{
				query = query.substring(0, caret - 1) + query.substring(caret);
				caret--;
			}
			else
			{
				// at the start of the text: nothing before the cursor to delete
				return;
			}
			refilter(true);
		}
		else
		{
			// nothing left to delete: back out of the section's page
			closeSection();
		}
	}

	public synchronized void moveSelection(int delta)
	{
		final int target = Math.max(0, Math.min(selected + delta, filtered.size() - 1));
		// going up, step over a heading to the setup above it. Going down is clamp's job.
		selected = isSkipped(target) && delta < 0 && target > 0 ? target - 1 : target;
		clamp();
		// keep the selection on screen, along with its heading when it's the first of a section
		if (selected < scroll)
		{
			scroll = isSkipped(selected - 1) && visibleRows > 1 ? selected - 1 : selected;
		}
		else if (selected >= scroll + visibleRows)
		{
			scroll = selected - visibleRows + 1;
		}
	}

	/**
	 * Move the selection by whole pages of visible rows.
	 */
	public synchronized void pageSelection(int pages)
	{
		moveSelection(pages * visibleRows);
	}

	/**
	 * The setup the keyboard selection is on, or null when nothing matches the search.
	 */
	public synchronized SetupEntry getSelectedSetup()
	{
		return selected < filtered.size() ? filtered.get(selected).getSetup() : null;
	}

	/**
	 * The row the keyboard selection is on, or null when nothing is listed.
	 */
	public synchronized PickerRow getSelectedRow()
	{
		return selected < filtered.size() ? filtered.get(selected) : null;
	}

	/**
	 * Drop the search text and focus and close the popup, e.g. after opening a setup.
	 */
	public synchronized void resetSearch()
	{
		// Back to the full list. If it was already showing, as when a setup is clicked in the list beside
		// the bank, it stays scrolled where it was.
		final boolean wasFiltered = !query.isEmpty();
		searchFocused = false;
		query = "";
		caret = 0;
		if (paletteOpen)
		{
			openSection = sectionBeforePalette;
		}
		refilter(wasFiltered);
		if (paletteOpen)
		{
			// the popup scrolls and changes page on its own; put the list beside the bank back where it was left
			paletteOpen = false;
			scroll = scrollBeforePalette;
			clamp();
		}
	}

	/**
	 * @param resetPosition go back to the top, for when what's listed has changed because of the search
	 */
	private void refilter(boolean resetPosition)
	{
		// a reload of the setups leaves the highlight alone; anything that changed the search has used it up
		querySelected &= !resetPosition && !query.isEmpty();
		revealSelection = false;
		final List<PickerRow> page = isPaged() ? page() : null;
		if (page != null)
		{
			filtered = page;
		}
		else if (query.isEmpty())
		{
			filtered = rows;
		}
		else
		{
			final String needle = query.toLowerCase(Locale.ROOT);
			List<PickerRow> matches = match(needle, SetupMatcher.Tier.EXACT);
			if (fuzzySearch)
			{
				// Only when the search would otherwise find nothing: allow for a typo, then for letters left out
				if (matches.isEmpty())
				{
					matches = match(needle, SetupMatcher.Tier.TYPO);
				}
				if (matches.isEmpty())
				{
					matches = match(needle, SetupMatcher.Tier.SUBSEQUENCE);
				}
			}
			filtered = Collections.unmodifiableList(matches);
		}
		if (resetPosition)
		{
			// start on the first setup rather than on its heading, even where headings can be picked
			selected = filtered.size() > 1 && filtered.get(0).isHeader() && !filtered.get(1).isHeader() ? 1 : 0;
			scroll = 0;
		}
		clamp();
	}

	/**
	 * Whether sections are being shown as pages: they have to be both wanted and there.
	 */
	private boolean isPaged()
	{
		return sectionPages && !rows.isEmpty() && rows.get(0).isHeader();
	}

	/**
	 * What to list when sections are pages, or null when it's the same as when they aren't: a search across
	 * all of them.
	 */
	private List<PickerRow> page()
	{
		final String needle = query.toLowerCase(Locale.ROOT);
		final List<PickerRow> page = new ArrayList<>();
		if (openSection == null)
		{
			if (!query.isEmpty())
			{
				return null;
			}
			// the list of sections
			for (PickerRow row : rows)
			{
				if (row.isHeader())
				{
					page.add(row);
				}
			}
			return Collections.unmodifiableList(page);
		}

		boolean inSection = false;
		for (PickerRow row : rows)
		{
			if (row.isHeader())
			{
				inSection = row.sameSection(openSection);
				if (inSection)
				{
					page.add(PickerRow.backFrom(row));
				}
			}
			else if (inSection && row.getSetup().getSearchName().contains(needle))
			{
				page.add(row);
			}
		}
		if (page.isEmpty())
		{
			// the section has gone, or has no setups left
			openSection = null;
			return page();
		}
		return Collections.unmodifiableList(page);
	}

	private List<PickerRow> match(String needle, SetupMatcher.Tier tier)
	{
		final List<PickerRow> matches = new ArrayList<>();
		// the heading of the section being gone through, until one of its setups matches and it gets listed
		PickerRow pendingHeader = null;
		boolean sectionMatches = false;
		for (PickerRow row : rows)
		{
			if (row.isHeader())
			{
				pendingHeader = row;
				// a section's name finds all of its setups
				sectionMatches = !row.isBuiltIn()
					&& SetupMatcher.matches(row.getSectionName().toLowerCase(Locale.ROOT), needle, tier);
			}
			else if (sectionMatches || SetupMatcher.matches(row.getSetup().getSearchName(), needle, tier, matcherWorkspace))
			{
				if (pendingHeader != null)
				{
					matches.add(pendingHeader);
					pendingHeader = null;
				}
				matches.add(row);
			}
		}
		return matches;
	}

	private void clamp()
	{
		scroll = Math.max(0, Math.min(scroll, filtered.size() - visibleRows));
		selected = Math.max(0, Math.min(selected, filtered.size() - 1));
		if (isSkipped(selected))
		{
			// a heading always has a setup below it
			selected++;
		}
	}

	/**
	 * Whether the row is a heading that the selection can't rest on.
	 */
	private boolean isSkipped(int index)
	{
		return !isPaged() && index >= 0 && index < filtered.size() && filtered.get(index).isHeader();
	}
}

package com.setuppicker;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.IntFunction;

/**
 * Draws the picker. Has no dependency on the game client so it can be rendered in tests.
 */
public final class PickerPainter
{
	private static final Color BORDER_OUTER = new Color(14, 13, 15);
	private static final Color FIELD_BACKGROUND = new Color(0, 0, 0, 110);
	private static final Color ROW_HOVER = new Color(255, 255, 255, 28);
	private static final Color SECTION_BACKGROUND = new Color(0, 0, 0, 60);
	private static final Color FAVORITE = new Color(255, 215, 0);
	private static final Color SCROLLBAR = new Color(120, 110, 90);

	private static final int ICON_WIDTH = 18;
	private static final int ICON_HEIGHT = 16;
	private static final int STAR_SIZE = 7;
	private static final int CLOCK_SIZE = 9;
	private static final int SCROLLBAR_WIDTH = 3;
	private static final int SECTION_ARROW_WIDTH = 5;

	private final PickerTheme theme;

	public PickerPainter(PickerTheme theme)
	{
		this.theme = theme;
	}

	/**
	 * @param mouse  mouse position on the canvas, or null
	 * @param icons  item id to image, or null to draw no icons. May return null for an image that isn't ready.
	 * @param status message for the empty list when there are no setups at all
	 */
	public void paint(Graphics2D g, PickerLayout layout, PickerModel.View view, Point mouse,
		IntFunction<BufferedImage> icons, Font font, String status)
	{
		g.setFont(font);
		final FontMetrics fm = g.getFontMetrics();

		final Rectangle bounds = layout.getBounds();
		g.setColor(theme.getBackground());
		g.fill(bounds);

		paintHeader(g, fm, layout, view, mouse);

		if (!layout.isCollapsed())
		{
			paintSearch(g, fm, layout.getSearch(), view);
			paintList(g, fm, layout, view, mouse, icons, status);
		}
		if (layout.isPalette())
		{
			g.setColor(theme.getMutedText());
			g.drawString(truncate(fm, "Up/Down: move   Enter: open   Esc: cancel",
				layout.getFooter().width - 8), layout.getFooter().x + 4, baseline(fm, layout.getFooter()));
		}

		g.setColor(theme.getBorder());
		g.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 3, bounds.height - 3);
		g.setColor(BORDER_OUTER);
		g.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
	}

	private void paintHeader(Graphics2D g, FontMetrics fm, PickerLayout layout, PickerModel.View view, Point mouse)
	{
		final Rectangle header = layout.getHeader();
		g.setColor(theme.getHeader());
		g.fill(header);
		if (!layout.isPalette() && mouse != null && header.contains(mouse))
		{
			g.setColor(ROW_HOVER);
			g.fill(header);
		}

		g.setColor(theme.getAccent());
		final String title;
		if (view.getTotal() <= 0)
		{
			title = "Bank Tags";
		}
		else if (!view.getQuery().isEmpty())
		{
			title = "Bank Tags (" + view.getRows().size() + "/" + view.getTotal() + ")";
		}
		else
		{
			title = "Bank Tags (" + view.getTotal() + ")";
		}
		if (layout.isUprightTab())
		{
			paintCollapsedTab(g, fm, header, title);
			return;
		}
		g.drawString(title, header.x + 7, baseline(fm, header));
		if (layout.isPalette())
		{
			return;
		}

		// collapse arrow: points down when open, right when collapsed
		final int cx = header.x + header.width - 11;
		final int cy = header.y + header.height / 2;
		final Polygon arrow = new Polygon();
		if (layout.isCollapsed())
		{
			arrow.addPoint(cx - 2, cy - 4);
			arrow.addPoint(cx + 3, cy);
			arrow.addPoint(cx - 2, cy + 4);
		}
		else
		{
			arrow.addPoint(cx - 4, cy - 2);
			arrow.addPoint(cx + 4, cy - 2);
			arrow.addPoint(cx, cy + 3);
		}
		g.fill(arrow);
	}

	/**
	 * The collapsed list in its upright form: a vertical tab with the expand arrow at the top and the title reading upwards.
	 */
	private void paintCollapsedTab(Graphics2D g, FontMetrics fm, Rectangle tab, String title)
	{
		final int arrowSpace = 16;
		final int cx = tab.x + tab.width / 2;
		final int cy = tab.y + arrowSpace / 2 + 2;
		final Polygon arrow = new Polygon();
		arrow.addPoint(cx - 2, cy - 4);
		arrow.addPoint(cx + 3, cy);
		arrow.addPoint(cx - 2, cy + 4);
		g.fill(arrow);

		// Turned a quarter turn about the tab's bottom left corner, x runs up the tab and y across it
		final AffineTransform upright = g.getTransform();
		final int bottom = tab.y + tab.height;
		g.rotate(-Math.PI / 2, tab.x, bottom);
		final int across = (tab.width - fm.getAscent() - fm.getDescent()) / 2 + fm.getAscent();
		g.drawString(truncate(fm, title, tab.height - arrowSpace - 12), tab.x + 7, bottom + across);
		g.setTransform(upright);
	}

	private void paintSearch(Graphics2D g, FontMetrics fm, Rectangle search, PickerModel.View view)
	{
		g.setColor(FIELD_BACKGROUND);
		g.fill(search);
		g.setColor(view.isSearchFocused() ? theme.getAccent() : theme.getBorder());
		g.drawRect(search.x, search.y, search.width - 1, search.height - 1);

		final int textX = search.x + 5;
		final int maxWidth = search.width - 10;
		if (view.getQuery().isEmpty() && !view.isSearchFocused())
		{
			g.setColor(theme.getMutedText());
			g.drawString("Search...", textX, baseline(fm, search));
			return;
		}

		// A search too long for the box is shown from far enough in to keep the cursor in view
		final String query = view.getQuery();
		final int caret = Math.min(view.getCaret(), query.length());
		int start = 0;
		while (start < caret && fm.stringWidth(query.substring(start, caret)) > maxWidth - 4)
		{
			start++;
		}
		int end = query.length();
		while (end > caret && fm.stringWidth(query.substring(start, end)) > maxWidth - 4)
		{
			end--;
		}
		final String shown = query.substring(start, end);

		if (view.isQuerySelected())
		{
			g.setColor(theme.getActiveRow());
			g.fillRect(textX - 1, search.y + 3, fm.stringWidth(shown) + 2, search.height - 6);
		}
		g.setColor(theme.getText());
		g.drawString(shown, textX, baseline(fm, search));

		if (view.isSearchFocused() && System.currentTimeMillis() / 500 % 2 == 0)
		{
			final int caretX = textX + fm.stringWidth(query.substring(start, caret)) + (caret == start ? 0 : 1);
			g.drawLine(caretX, search.y + 4, caretX, search.y + search.height - 5);
		}
	}

	private void paintList(Graphics2D g, FontMetrics fm, PickerLayout layout, PickerModel.View view, Point mouse,
		IntFunction<BufferedImage> icons, String status)
	{
		final Rectangle list = layout.getList();
		final List<PickerRow> rows = view.getRows();

		if (rows.isEmpty())
		{
			final String message = view.getTotal() > 0 ? "No matches" : status;
			g.setColor(theme.getMutedText());
			g.drawString(truncate(fm, message, list.width - 8), list.x + 4, baseline(fm, list));
			return;
		}

		final boolean scrollable = rows.size() > layout.getVisibleRows();
		final int rowWidth = list.width - (scrollable ? SCROLLBAR_WIDTH + 2 : 0);

		for (int i = 0; i < layout.getVisibleRows(); i++)
		{
			final int index = view.getScroll() + i;
			if (index >= rows.size())
			{
				break;
			}
			final Rectangle row = layout.getRow(i);
			row.width = rowWidth;
			final boolean hovered = mouse != null && row.contains(mouse);
			final boolean selected = view.isSearchFocused() && index == view.getSelected();
			if (rows.get(index).isHeader())
			{
				paintSectionHeader(g, fm, row, rows.get(index), view.isSectionPages(), hovered, selected);
				continue;
			}
			final SetupEntry setup = rows.get(index).getSetup();

			final boolean active = setup.getName().equals(view.getActiveSetup());
			if (active)
			{
				g.setColor(theme.getActiveRow());
				g.fill(row);
			}
			if (hovered || selected)
			{
				g.setColor(ROW_HOVER);
				g.fill(row);
			}
			if (selected)
			{
				g.setColor(theme.getAccent());
				g.drawRect(row.x, row.y, row.width - 1, row.height - 1);
			}

			int textX = row.x + 4;
			if (icons != null)
			{
				final BufferedImage icon = icons.apply(setup.getIconItemId());
				if (icon != null)
				{
					g.drawImage(icon, row.x + 2, row.y + (row.height - ICON_HEIGHT) / 2, ICON_WIDTH, ICON_HEIGHT, null);
				}
				textX = row.x + 2 + ICON_WIDTH + 4;
			}

			int textRight = row.x + row.width - 4;
			if (setup.isFavorite())
			{
				textRight -= STAR_SIZE + 3;
				paintStar(g, textRight + 3 + STAR_SIZE / 2, row.y + row.height / 2);
			}
			if (rows.get(index).isRecent())
			{
				textRight -= CLOCK_SIZE + 3;
				paintClock(g, textRight + 3 + CLOCK_SIZE / 2, row.y + row.height / 2);
			}

			g.setColor(setup.getDisplayColor() != null ? setup.getDisplayColor() : (active ? theme.getAccent() : theme.getText()));
			g.drawString(truncate(fm, setup.getName(), textRight - textX), textX, baseline(fm, row));
		}

		if (scrollable)
		{
			final int barHeight = Math.max(8, list.height * layout.getVisibleRows() / rows.size());
			final int maxScroll = rows.size() - layout.getVisibleRows();
			final int barY = list.y + (list.height - barHeight) * view.getScroll() / maxScroll;
			g.setColor(SCROLLBAR);
			g.fillRect(list.x + list.width - SCROLLBAR_WIDTH, barY, SCROLLBAR_WIDTH, barHeight);
		}
	}

	/**
	 * @param pickable the heading leads to the section's page, or back from it, so gets an arrow saying which
	 */
	private void paintSectionHeader(Graphics2D g, FontMetrics fm, Rectangle row, PickerRow header,
		boolean pickable, boolean hovered, boolean selected)
	{
		g.setColor(SECTION_BACKGROUND);
		g.fill(row);
		if (pickable && (hovered || selected))
		{
			g.setColor(ROW_HOVER);
			g.fill(row);
		}
		if (pickable && selected)
		{
			g.setColor(theme.getAccent());
			g.drawRect(row.x, row.y, row.width - 1, row.height - 1);
		}

		// muted reads as disabled, which a heading that can be picked isn't
		final Color color = header.getSectionColor() != null ? header.getSectionColor() : (pickable ? theme.getText() : theme.getMutedText());
		final int cy = row.y + row.height / 2;
		int textX = row.x + 4;
		int right = row.x + row.width - 4;
		g.setColor(color);
		if (header.isBack())
		{
			paintArrow(g, textX, cy, -1);
			textX += SECTION_ARROW_WIDTH + 4;
		}
		else if (pickable)
		{
			right -= SECTION_ARROW_WIDTH;
			paintArrow(g, right, cy, 1);
			right -= 4;
		}

		final String name = truncate(fm, header.getSectionName(), right - textX);
		g.drawString(name, textX, baseline(fm, row));

		// rule filling the rest of the row
		final int ruleX = textX + fm.stringWidth(name) + 5;
		if (ruleX < right)
		{
			g.setColor(theme.getBorder());
			g.drawLine(ruleX, cy, right - 1, cy);
		}
	}

	/**
	 * A small arrowhead with its flat side at x, pointing right for a direction of 1 and left for -1.
	 */
	private void paintArrow(Graphics2D g, int x, int cy, int direction)
	{
		final int base = direction > 0 ? x : x + SECTION_ARROW_WIDTH;
		final Polygon arrow = new Polygon();
		arrow.addPoint(base, cy - 4);
		arrow.addPoint(base + direction * SECTION_ARROW_WIDTH, cy);
		arrow.addPoint(base, cy + 4);
		g.fill(arrow);
	}

	/**
	 * Marks a recently used setup: a clock face showing about three o'clock.
	 */
	private void paintClock(Graphics2D g, int cx, int cy)
	{
		final int radius = CLOCK_SIZE / 2;
		g.setColor(theme.getMutedText());
		g.drawOval(cx - radius, cy - radius, CLOCK_SIZE - 1, CLOCK_SIZE - 1);
		g.drawLine(cx, cy, cx, cy - radius + 2);
		g.drawLine(cx, cy, cx + radius - 2, cy);
	}

	private void paintStar(Graphics2D g, int cx, int cy)
	{
		final Polygon star = new Polygon();
		for (int i = 0; i < 10; i++)
		{
			final double radius = i % 2 == 0 ? STAR_SIZE / 2.0 + 0.5 : STAR_SIZE / 4.0;
			final double angle = -Math.PI / 2 + i * Math.PI / 5;
			star.addPoint((int) Math.round(cx + radius * Math.cos(angle)), (int) Math.round(cy + radius * Math.sin(angle)));
		}
		g.setColor(FAVORITE);
		g.fill(star);
	}

	private static int baseline(FontMetrics fm, Rectangle box)
	{
		return box.y + (box.height - fm.getAscent() - fm.getDescent()) / 2 + fm.getAscent();
	}

	private static String truncate(FontMetrics fm, String text, int maxWidth)
	{
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		final String ellipsis = "...";
		String cut = text;
		while (!cut.isEmpty() && fm.stringWidth(cut + ellipsis) > maxWidth)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut + ellipsis;
	}
}

package com.setuppicker;

import java.awt.Color;

/**
 * One line of the picker's list: a setup, or the heading of the section the setups below it belong to.
 */
public final class PickerRow
{
	/**
	 * Heading for the setups that aren't in any section.
	 */
	public static final PickerRow UNASSIGNED = new PickerRow(null, "Unassigned", null, false, false, 1);

	/**
	 * Heading for the recently used setups, when the list is in sections.
	 */
	public static final PickerRow RECENT = new PickerRow(null, "Recent", null, false, false, 2);

	private final SetupEntry setup;
	private final String sectionName;
	private final Color sectionColor;
	private final boolean back;
	private final boolean recent;

	// 0 for a setup or a section of the user's; otherwise which of the headings above this is, or leads back from
	private final int builtIn;

	private PickerRow(SetupEntry setup, String sectionName, Color sectionColor, boolean back, boolean recent, int builtIn)
	{
		this.recent = recent;
		this.builtIn = builtIn;
		this.setup = setup;
		this.sectionName = sectionName;
		this.sectionColor = sectionColor;
		this.back = back;
	}

	public static PickerRow of(SetupEntry setup)
	{
		return new PickerRow(setup, null, null, false, false, 0);
	}

	/**
	 * A setup listed at the top for having been used recently.
	 */
	public static PickerRow recent(SetupEntry setup)
	{
		return new PickerRow(setup, null, null, false, true, 0);
	}

	public static PickerRow header(SetupSection section)
	{
		return new PickerRow(null, section.getName(), section.getDisplayColor(), false, false, 0);
	}

	/**
	 * The heading at the top of a section's own page, which leads back to the list of sections.
	 */
	public static PickerRow backFrom(PickerRow header)
	{
		return new PickerRow(null, header.sectionName, header.sectionColor, true, false, header.builtIn);
	}

	public boolean isHeader()
	{
		return setup == null;
	}

	/**
	 * Whether this setup is listed here for having been used recently.
	 */
	public boolean isRecent()
	{
		return recent;
	}

	/**
	 * Whether this heading is one of the picker's own rather than a section from Inventory Setups.
	 */
	public boolean isBuiltIn()
	{
		return builtIn != 0;
	}

	/**
	 * Whether this is the heading of a section's page, for going back to the list of sections.
	 */
	public boolean isBack()
	{
		return back;
	}

	/**
	 * Whether this heading and the other are for the same section.
	 */
	boolean sameSection(PickerRow other)
	{
		// a section the user happened to name "Unassigned" or "Recent" is not the built-in one
		return builtIn == other.builtIn && sectionName.equals(other.sectionName);
	}

	/**
	 * The setup on this row, or null for a heading.
	 */
	public SetupEntry getSetup()
	{
		return setup;
	}

	/**
	 * The section name of a heading, or null for a setup.
	 */
	public String getSectionName()
	{
		return sectionName;
	}

	/**
	 * The color the user gave the section in Inventory Setups, or null for none.
	 */
	public Color getSectionColor()
	{
		return sectionColor;
	}
}

package com.setuppicker;

import java.awt.Color;

/**
 * The colors the picker is drawn in. The defaults suit the game's own interfaces; they can be changed in the
 * plugin's settings, for instance to match a resource pack.
 */
public final class PickerTheme
{
	static final Color DEFAULT_BACKGROUND = new Color(40, 34, 26, 240);
	static final Color DEFAULT_HEADER = new Color(62, 53, 41);
	static final Color DEFAULT_BORDER = new Color(87, 80, 64);
	static final Color DEFAULT_ACCENT = new Color(255, 152, 31);
	static final Color DEFAULT_TEXT = new Color(235, 228, 210);

	public static final PickerTheme DEFAULT = new PickerTheme(DEFAULT_BACKGROUND, DEFAULT_HEADER, DEFAULT_BORDER,
		DEFAULT_ACCENT, DEFAULT_TEXT);

	private static final int ACTIVE_ROW_ALPHA = 70;
	private static final double MUTED_TEXT_FADE = 0.45;

	private final Color background;
	private final Color header;
	private final Color border;
	private final Color accent;
	private final Color text;
	private final Color mutedText;
	private final Color activeRow;

	/**
	 * @param accent the title, the keyboard selection, the focused search box and the open setup
	 */
	public PickerTheme(Color background, Color header, Color border, Color accent, Color text)
	{
		this.background = background;
		this.header = header;
		this.border = border;
		this.accent = accent;
		this.text = text;
		// Hints and placeholders: the text color, faded part of the way into the background
		this.mutedText = mix(text, background, MUTED_TEXT_FADE);
		this.activeRow = new Color(accent.getRed(), accent.getGreen(), accent.getBlue(), ACTIVE_ROW_ALPHA);
	}

	private static Color mix(Color from, Color to, double amount)
	{
		return new Color(
			(int) Math.round(from.getRed() + (to.getRed() - from.getRed()) * amount),
			(int) Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * amount),
			(int) Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * amount));
	}

	public Color getBackground()
	{
		return background;
	}

	public Color getHeader()
	{
		return header;
	}

	public Color getBorder()
	{
		return border;
	}

	public Color getAccent()
	{
		return accent;
	}

	public Color getText()
	{
		return text;
	}

	public Color getMutedText()
	{
		return mutedText;
	}

	public Color getActiveRow()
	{
		return activeRow;
	}
}

package com.setuppicker;

import java.awt.event.InputEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.OSType;

/**
 * The "primary" shortcut modifier of the platform being played on: Cmd on a Mac, Ctrl elsewhere.
 *
 * <p>The Platform Keys plugin has a setting to force one platform's keys regardless of the computer. When that
 * plugin hasn't been switched off its choice is followed, so this plugin's shortcut uses the same modifier as its bank search.
 */
@Singleton
public class PlatformModifier
{
	// Platform Keys' config group, its profile setting, and the values that setting takes (its KeyProfile enum)
	private static final String PLATFORM_KEYS_GROUP = "platformkeys";
	private static final String PLATFORM_KEYS_PROFILE = "profile";
	private static final String PROFILE_MAC = "MAC";
	private static final String PROFILE_WINDOWS = "WINDOWS";
	// Where RuneLite records whether the Platform Keys plugin is switched on
	private static final String RUNELITE_GROUP = "runelite";
	private static final String PLATFORM_KEYS_ENABLED = "platformkeysplugin";

	private final ConfigManager configManager;

	@Inject
	PlatformModifier(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * @return {@link InputEvent#META_DOWN_MASK} or {@link InputEvent#CTRL_DOWN_MASK}
	 */
	public int get()
	{
		// plugins count as on until they have been switched off, so there may be no value at all
		final boolean platformKeysEnabled = !"false".equals(configManager.getConfiguration(RUNELITE_GROUP, PLATFORM_KEYS_ENABLED));
		return resolve(platformKeysEnabled ? configManager.getConfiguration(PLATFORM_KEYS_GROUP, PLATFORM_KEYS_PROFILE) : null,
			OSType.getOSType() == OSType.MacOS);
	}

	/**
	 * @param platformKeysProfile Platform Keys' profile setting, or null when that plugin isn't in use
	 */
	static int resolve(String platformKeysProfile, boolean onMac)
	{
		final boolean mac;
		if (PROFILE_MAC.equals(platformKeysProfile))
		{
			mac = true;
		}
		else if (PROFILE_WINDOWS.equals(platformKeysProfile))
		{
			mac = false;
		}
		else
		{
			// no override, or Platform Keys' own auto-detect
			mac = onMac;
		}
		return mac ? InputEvent.META_DOWN_MASK : InputEvent.CTRL_DOWN_MASK;
	}
}

package com.setuppicker;

/** Tracks active-tag transitions on the client thread without retaining a previous profile's state. */
final class RecentTagTracker
{
	private String previous;

	boolean observe(String active, boolean enabled)
	{
		final String current = active == null ? "" : active;
		final boolean opened = previous != null && !current.isEmpty() && !current.equals(previous);
		previous = current;
		return enabled && opened;
	}

	void reset()
	{
		// The first observation establishes a baseline, including a restored active tag.
		previous = null;
	}
}

